// Builds the multi-page ICS website demo into public/demos/ics/.
// Run: node scripts/demos/ics-site/build.cjs
// Static HTML per page (good for search engines), shared site.css / site.js, EN text in the HTML with
// data-el / data-fr for the in-page language switch. Connected to the CRM demo through ../ics-crm/store.js.
const fs = require("fs"), path = require("path");
const OUT = path.join(__dirname, "../../../public/demos/ics");
const SV = require("./services.cjs");
const SITE = "https://www.icsgr.com";

const ea = s => String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
const eh = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
// text node in 3 languages: t(["en","el","fr"], "h3", 'class="x"')
const t = (a, tag = "span", at = "") => `<${tag}${at ? " " + at : ""} data-el="${ea(a[1])}" data-fr="${ea(a[2] ?? a[0])}">${eh(a[0])}</${tag}>`;
const T3 = (en, el, fr) => [en, el, fr ?? en];

const NAVS = [["services.html", ["Services", "Υπηρεσίες", "Services"]], ["pricing.html", ["Prices & plans", "Τιμές & συνδρομές", "Tarifs & abonnements"]], ["about.html", ["About", "Η εταιρεία", "À propos"]], ["news.html", ["News", "Νέα", "Actualités"]], ["contact.html", ["Contact", "Επικοινωνία", "Contact"]]];

function layout({ file, title, desc, body, ld = [], active = "", crumbs = null }) {
  const org = { "@context": "https://schema.org", "@type": "ProfessionalService", name: "Integrated Consulting Services (ICS)", url: SITE, telephone: "+1-866-496-4539", email: "info@icsgr.com", foundingDate: "2007", areaServed: ["CA", "US", "GR", "CY"], availableLanguage: ["en", "el", "fr"],
    address: { "@type": "PostalAddress", streetAddress: "1315 Lawrence Avenue East, Unit 203", addressLocality: "Toronto", addressRegion: "ON", postalCode: "M3A 3R3", addressCountry: "CA" },
    department: [["Montreal", "800 Boul. Chomedey, Tour C, Suite 120", "Laval", "CA", "+1-514-270-7337"], ["New York", "32-75 Steinway Street, Suite 207", "Astoria, NY", "US", "+1-718-360-1657"], ["Athens", "233 Leof. Syggrou", "Nea Smyrni", "GR", "+30-210-3230205"], ["Thessaloniki", "3 P. Vlachakou Street", "Thessaloniki", "GR", "+30-2310-704043"], ["Nicosia", "24 Grigoriou Xenopoulou Str.", "Nicosia", "CY", "+357-22262268"]].map(([n, s, l, c, p]) => ({ "@type": "ProfessionalService", name: "ICS " + n, telephone: p, address: { "@type": "PostalAddress", streetAddress: s, addressLocality: l, addressCountry: c } })) };
  const bc = crumbs && { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: [["Home", "demo.html"], ...crumbs].map(([n, u], i) => { u = u || file; return { "@type": "ListItem", position: i + 1, name: n, item: `${SITE}/${u === "demo.html" ? "" : u.replace(".html", "/")}` }; }) };
  const canon = `${SITE}/${file === "demo.html" ? "" : file.replace(".html", "/")}`;
  const svcMenu = SV.map(s => `<a href="${s.slug}.html"><i>${s.ic}</i><span>${t(s.name, "b")}${t(s.short.map(x => x.split(/[.,]/)[0]), "small")}</span></a>`).join("");
  return `<!doctype html>
<html lang="en" class="notes">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex, nofollow"><!-- demo only: the live site is indexable -->
<meta name="theme-color" content="#0f1512">
${t(title, "title")}
<meta name="description" content="${ea(desc[0])}">
<link rel="canonical" href="${canon}">
<link rel="alternate" hreflang="en" href="${canon}"><link rel="alternate" hreflang="el" href="${canon.replace(SITE, SITE + "/el")}"><link rel="alternate" hreflang="fr" href="${canon.replace(SITE, SITE + "/fr")}">
<meta property="og:type" content="website"><meta property="og:site_name" content="ICS · Integrated Consulting Services"><meta property="og:title" content="${ea(title[0])}"><meta property="og:description" content="${ea(desc[0])}"><meta property="og:url" content="${canon}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&family=Noto+Serif+Display:ital,wght@0,300;1,300;1,400&display=swap" rel="stylesheet">
<link rel="stylesheet" href="site.css?v=4">
${[org, bc, ...ld].filter(Boolean).map(j => `<script type="application/ld+json">${JSON.stringify(j)}</script>`).join("\n")}
<!-- OpenSite redesign demo for Integrated Consulting Services (icsgr.com). Content from icsgr.com (Nov 2026).
     Generated by scripts/demos/ics-site/build.cjs. Connected to the CRM demo through ../ics-crm/store.js.
     Payments are simulated. Prices marked .ph are placeholders for ICS to set. -->
<script src="../ics-crm/store.js?v=4"></script>
<script>(function(){var h=document.documentElement;try{var q=new URLSearchParams(location.search);if(q.has("clean")){h.classList.remove("notes");h.classList.add("clean");sessionStorage.setItem("ics-clean","1")}else if(sessionStorage.getItem("ics-clean")){h.classList.remove("notes");h.classList.add("clean")}}catch(e){}})();</script>
</head>
<body>
<header class="nav">
  <div class="wrap">
    <a class="logo" href="demo.html" aria-label="ICS home"><i>•••</i>ICS<small>Integrated Consulting Services</small></a>
    <nav class="nav-l" aria-label="Main">
      <span class="dd"><a href="services.html" class="${active === "services.html" ? "on" : ""}">${t(NAVS[0][1])}</a><span class="card ddm">${svcMenu}</span></span>
      ${NAVS.slice(1).map(([h, l]) => `<a href="${h}" class="${active === h ? "on" : ""}">${t(l)}</a>`).join("")}
    </nav>
    <div class="nav-r">
      <div class="lang"><button class="on" data-l="en">EN</button><button data-l="el">ΕΛ</button><button data-l="fr">FR</button></div>
      <a class="btn line s" href="portal.html">${t(["My case", "Η υπόθεσή μου", "Mon dossier"])}</a>
      <a class="btn lime s" href="book.html">${t(["Book a consultation", "Κλείστε ραντεβού", "Prendre rendez-vous"])}</a>
      <button class="burger" aria-label="Menu">☰</button>
    </div>
  </div>
</header>
<nav class="mnav" aria-label="Mobile">
  <a href="services.html">${t(NAVS[0][1])}</a>${SV.map(s => `<a class="sub" href="${s.slug}.html">${s.ic} ${t(s.name)}</a>`).join("")}
  ${NAVS.slice(1).map(([h, l]) => `<a href="${h}">${t(l)}</a>`).join("")}<a href="quote.html">${t(["Get a quote", "Ζητήστε προσφορά", "Demander une soumission"])}</a>
  <a class="btn lime" href="book.html">${t(["Book a consultation", "Κλείστε ραντεβού", "Prendre rendez-vous"])}</a><a class="btn" href="portal.html">${t(["My case", "Η υπόθεσή μου", "Mon dossier"])}</a>
</nav>
<main>
${crumbs ? `<div class="wrap" style="padding-top:22px"><nav class="crumbs" aria-label="Breadcrumb"><a href="demo.html">${t(["Home", "Αρχική", "Accueil"])}</a>${crumbs.map(([n, u, l]) => `<span>${u ? `<a href="${u}">${t(l || [n, n, n])}</a>` : t(l || [n, n, n])}</span>`).join("")}</nav></div>` : ""}
${body}
</main>
${footer()}
<div class="ov" id="ov"><div class="card pay" id="pay"></div></div>
<a class="staff" href="../ics-crm/demo.html" target="_blank" id="staffBtn">↗ ICS Workspace (CRM)</a>
<button class="notes-t" id="notesT">Notes</button>
<div class="toast" id="toast"></div>
<script src="site.js?v=4"></script>
<script src="chat.js?v=1"></script>
</body>
</html>
`;
}

