/* ================= write ================= */
fs.mkdirSync(OUT, { recursive: true });
const css = fs.readFileSync(path.join(__dirname, "base.css"), "utf8") + fs.readFileSync(path.join(__dirname, "ext.css"), "utf8");
fs.writeFileSync(path.join(OUT, "site.css"), css);
let core = fs.readFileSync(path.join(__dirname, "core.js"), "utf8").replace(/^<script>\s*/, "");
let js = "/* ICS website demo · generated by scripts/demos/ics-site/build.cjs */\n(function(){\n" + core + "\n" + fs.readFileSync(path.join(__dirname, "commerce.js"), "utf8") + "\n})();\n";
fs.writeFileSync(path.join(OUT, "site.js"), js);
fs.copyFileSync(path.join(__dirname, "chat.js"), path.join(OUT, "chat.js"));
let n = 0;
for (const [f, fn] of Object.entries(pages)) { fs.writeFileSync(path.join(OUT, f), fn()); n++; }
console.log(`ICS site: ${n} pages, site.css ${css.length} B, site.js ${js.length} B → ${OUT}`);
